// AgentServiceHandler is an implementation of the clabgen.v1.AgentService service.
type AgentServiceHandler interface {
	GetInfo(context.Context, *connect.Request[v1.GetInfoRequest]) (*connect.Response[v1.GetInfoResponse], error)
	// Ports are the physical (veth) interfaces of the container.
	ListPorts(context.Context, *connect.Request[v1.ListPortsRequest]) (*connect.Response[v1.ListPortsResponse], error)
	SetPortAdmin(context.Context, *connect.Request[v1.SetPortAdminRequest]) (*connect.Response[v1.SetPortAdminResponse], error)
	// Devices are emulated endpoints (MAC + VLAN stack, later IP) on a port.
	ListDevices(context.Context, *connect.Request[v1.ListDevicesRequest]) (*connect.Response[v1.ListDevicesResponse], error)
	CreateDevice(context.Context, *connect.Request[v1.CreateDeviceRequest]) (*connect.Response[v1.CreateDeviceResponse], error)
	// UpdateDevice replaces a device's port, MAC and VLAN stack (the name is
	// the key). Protocols on the device restart.
	UpdateDevice(context.Context, *connect.Request[v1.UpdateDeviceRequest]) (*connect.Response[v1.UpdateDeviceResponse], error)
	DeleteDevice(context.Context, *connect.Request[v1.DeleteDeviceRequest]) (*connect.Response[v1.DeleteDeviceResponse], error)
	// GetDeviceIP returns a device's effective addresses, neighbor cache and
	// IP counters.
	GetDeviceIP(context.Context, *connect.Request[v1.GetDeviceIPRequest]) (*connect.Response[v1.GetDeviceIPResponse], error)
	// ResolveNeighbor resolves an address with ARP or ND (an off-link address
	// resolves the device's gateway).
	ResolveNeighbor(context.Context, *connect.Request[v1.ResolveNeighborRequest]) (*connect.Response[v1.ResolveNeighborResponse], error)
	ClearNeighbors(context.Context, *connect.Request[v1.ClearNeighborsRequest]) (*connect.Response[v1.ClearNeighborsResponse], error)
	// ListReceivedFlows returns the signed flow packets devices have received
	// (one-way loss, reordering, latency and outages per flow ID).
	ListReceivedFlows(context.Context, *connect.Request[v1.ListReceivedFlowsRequest]) (*connect.Response[v1.ListReceivedFlowsResponse], error)
	ClearReceivedFlows(context.Context, *connect.Request[v1.ClearReceivedFlowsRequest]) (*connect.Response[v1.ClearReceivedFlowsResponse], error)
	// Protocol types are the plugins compiled into the agent. Each publishes a
	// JSON schema for its config and for each action's arguments.
	ListProtocolTypes(context.Context, *connect.Request[v1.ListProtocolTypesRequest]) (*connect.Response[v1.ListProtocolTypesResponse], error)
	// Protocols are running instances of a protocol type bound to a device.
	ListProtocols(context.Context, *connect.Request[v1.ListProtocolsRequest]) (*connect.Response[v1.ListProtocolsResponse], error)
	GetProtocol(context.Context, *connect.Request[v1.GetProtocolRequest]) (*connect.Response[v1.GetProtocolResponse], error)
	CreateProtocol(context.Context, *connect.Request[v1.CreateProtocolRequest]) (*connect.Response[v1.CreateProtocolResponse], error)
	UpdateProtocol(context.Context, *connect.Request[v1.UpdateProtocolRequest]) (*connect.Response[v1.UpdateProtocolResponse], error)
	DeleteProtocol(context.Context, *connect.Request[v1.DeleteProtocolRequest]) (*connect.Response[v1.DeleteProtocolResponse], error)
	RunProtocolAction(context.Context, *connect.Request[v1.RunProtocolActionRequest]) (*connect.Response[v1.RunProtocolActionResponse], error)
	// Stops an instance keeping its config, or starts it again.
	SetProtocolDisabled(context.Context, *connect.Request[v1.SetProtocolDisabledRequest]) (*connect.Response[v1.SetProtocolDisabledResponse], error)
	// Device groups are many devices from one template, each with the same
	// set of protocol instances. Members are listed as ordinary devices and
	// protocols (with group set) and change only through their group.
	ListDeviceGroups(context.Context, *connect.Request[v1.ListDeviceGroupsRequest]) (*connect.Response[v1.ListDeviceGroupsResponse], error)
	GetDeviceGroup(context.Context, *connect.Request[v1.GetDeviceGroupRequest]) (*connect.Response[v1.GetDeviceGroupResponse], error)
	CreateDeviceGroup(context.Context, *connect.Request[v1.CreateDeviceGroupRequest]) (*connect.Response[v1.CreateDeviceGroupResponse], error)
	// UpdateDeviceGroup replaces a group's spec; members whose rendered
	// device and protocols are unchanged keep running.
	UpdateDeviceGroup(context.Context, *connect.Request[v1.UpdateDeviceGroupRequest]) (*connect.Response[v1.UpdateDeviceGroupResponse], error)
	DeleteDeviceGroup(context.Context, *connect.Request[v1.DeleteDeviceGroupRequest]) (*connect.Response[v1.DeleteDeviceGroupResponse], error)
	// RunGroupAction runs a protocol action on some or all members.
	RunGroupAction(context.Context, *connect.Request[v1.RunGroupActionRequest]) (*connect.Response[v1.RunGroupActionResponse], error)
	// Disables (stops, keeping config) or enables a group's protocols on
	// selected members; on all of them it is recorded in the group spec.
	SetGroupDisabled(context.Context, *connect.Request[v1.SetGroupDisabledRequest]) (*connect.Response[v1.SetGroupDisabledResponse], error)
	WatchEvents(context.Context, *connect.Request[v1.WatchEventsRequest], *connect.ServerStream[v1.Event]) error
	// Scenarios are the whole agent config as YAML.
	GetScenario(context.Context, *connect.Request[v1.GetScenarioRequest]) (*connect.Response[v1.GetScenarioResponse], error)
	ApplyScenario(context.Context, *connect.Request[v1.ApplyScenarioRequest]) (*connect.Response[v1.ApplyScenarioResponse], error)
}

